from save_review import save
save(1261,{2:'中子激光投射炮是帝国使用的一种强大而罕见的武器，可安装在瓦尔多反坦克车、西卡然猎手、军刀突击坦克和刻耳柏洛斯重型反坦克车上。它是黑暗科技时代的遗物，虽然名称带有“激光”，实际向目标发射的却是中子，而非光子。',4:'Sicaran Venator with a Neutron Laser Projector 装备中子激光投射炮的西卡然猎手',7:'这种武器的原理尚未被充分理解，而且极不稳定，却能释放出威力超过帝国其他同等尺寸武器的能量冲击。它射出的中子束会使物质发生爆炸性崩解，击碎目标的分子结构，连最致密的材料也能摧毁。与此同时，强大的电磁冲击脉冲会令电子系统失效，穿透性辐射则破坏生物组织；不过，这些效应只对缺乏超重型坦克那种厚重屏蔽和大量防护材料的载具有效。它因此十分适合反坦克作战，但中子束若未能将全部能量传递给目标，便可能形成危险的反馈回路，损伤武器自身。供能的中子线圈电弧反应堆本身也不稳定，缺少必要的反应堆屏蔽时，操作会很危险。',9:'大远征和荷鲁斯之乱时期，西卡然猎手坦克与军刀反坦克车也曾安装这种武器；即使在当时，技术专家对其系统和原理也知之甚少。',12:'中子爆破炮是大型中子激光投射炮的衍生型号，安装于军刀突击坦克。它的构造原理与西卡然猎手使用的较大型中子炮相同，但电容器和能源包释放的强烈辐射极其有害，最终甚至会损坏军刀自身的控制系统。'},notes={7:'原文比较范围是同等尺寸的帝国武器，原译遗漏此限制；关于辐射和反馈机制的描述保留为设定，不扩展解释。'},terms=[('Neutron Laser Projector','中子激光投射炮'),('Neutron Blaster','中子爆破炮')])
save(1262,{2:'转化光束投射炮是一种重型能量武器，常简称转化光束炮或光束炮。',5:'转化光束炮发射高强度能量束，将物质转变为纯能量。重装甲或致密材料会因自身物质发生爆炸而被撕裂。目标越致密，被光束击中的物质越多，释放的能量也越大，因此这类武器特别适合打击重装部队、载具和建筑。光束还会转化沿途的周围大气，通常离发射端越远，强度越高；当能量积聚到临界程度，便会以猛烈爆炸的方式释放。',7:'Conversion Beamer 转化光束炮',9:'终结者星际战士曾偶尔携带小型转化光束炮，在探索太空废船时切开舱壁，但如今已很少这样做。',11:'转化光束炮的一大缺点是极其庞大、沉重：投射管周围需要排列许多大型电容器。操作时，武器还必须保持绝对静止，否则光束强度便会消散，使射击失效。因此，它通常安装在自行轮式炮架或反重力平台上，由操作人员在安全距离外遥控。小型手持版本的使用者则必须穿上带有特殊抓地爪的靴子，以保持稳固。另一个问题是蓄能时间：虽然只需约一秒，仍足以让目标移动或逃离射界。',13:'Space Marine Master of the Forge with conversion beamer 装备转化光束炮的星际战士铸造大师',16:'重型转化光束炮——普通转化光束炮的加强版本，是威力惊人、原理却知之甚少的古老遗物武器。有时可见于蔑视者型无畏机甲、屠戮者恶魔引擎，以及火卫二型处刑者掠食者战车。',18:'转化光束加农炮——罕见而精密的转化光束技术中，现存体积最大的实例之一，安装于牛头怪型骑士。',20:'转化光束分解器——巨大的泰坦级转化光束武器，可安装在战犬级泰坦臂部，或掠夺者级泰坦的背甲上。',22:'转化光束耗散器——巨大的泰坦级转化光束武器，安装于恐狼泰坦背甲。',24:'消除炮——安装于战将级泰坦臂部的巨型转化光束武器，是底稿所述已知最大的此类武器。',26:'SP型转化光束炮——沃坦联盟使用的转化光束炮。',28:'SP型重型转化光束炮——SP型转化光束炮的更大型版本，装备于赫卡顿陆行要塞等沃坦联盟载具。'},notes={2:'Conversion Beamer沿251—297篇转化光束炮统一；本篇原转换光束枪、转换光束投射器等异译保留对照。',18:'Knight Asterius对应已核官方完整单位“牛头怪型阿卡斯托斯骑士”；原译只写阿卡斯托斯会漏掉具体型号。',26:'SP为原文型号标记，英文未在此解释缩写，故保留字母，不沿原译擅改成聚能。'},terms=[('Conversion Beam Projector','转化光束投射炮'),('Conversion Beamer','转化光束炮'),('Heavy Conversion Beamer','重型转化光束炮'),('Conversion Beam Cannon','转化光束加农炮'),('Conversion Beam Dissolutor','转化光束分解器'),('Conversion Beam Dissipator','转化光束耗散器'),('Extirpator Cannon','消除炮'),('SP Conversion Beamer','SP型转化光束炮'),('SP Heavy Conversion Beamer','SP型重型转化光束炮'),('Hekaton Land Fortress','赫卡顿陆行要塞')],title='转化光束投射炮 Conversion Beam Projector')
save(1263,{2:'安巴里克爪是机械修会安巴里克修会安装在战争机器上的防御系统。一些与安维鲁斯星系庞大铸造世界群关系密切的星际战士军团，也将它整合进载具。它利用一组电化学电容器，经由车体释放强大的电磁脉冲冲击，能够电毙并焚烧附近生物，也能烧毁敌方机械。这种武器曾在大远征和荷鲁斯之乱期间投入使用。'},notes={2:'Anbaric作为专名沿篇名音译，原正文另译电爪／电力修会；保持武器与组织词根一致。其所属为机械修会，不套用审判庭的Ordo译法。'},terms=[('Anbaric Claw','安巴里克爪'),('Anbaric Order','安巴里克修会')])
save(1264,{2:'火焰武器会喷出大量火焰或燃烧物，被多个种族和军队使用。它能越过掩体的保护，一次杀伤大量敌人，因此备受重视。',4:'灵族火龙主教有时使用一种称为“龙息火焰喷射器”的武器。',6:'欧克所用型号，参见“欧克火焰武器”。',8:'帝国的火焰武器种类繁多，从紧凑的手持火焰喷射器，甚至微型火焰指环武器，一直到只能安装于重型载具和帝国泰坦上的大型装备。',12:'歼灭者——可加装于近战或远程武器上的小型一次性火焰武器，通常由救赎主义者、兄弟会民兵等狂信徒使用。',14:'炼狱加农炮——一种巨大的武器，单次射击便可摧毁整支部队，常安装于地狱犬和献祭者。',16:'炼狱炮——安装在战犬级侦察泰坦上的武器，是炼狱加农炮的更大型版本。',18:'焚化枪——审判庭尤其是灰骑士使用的武器，以经过祝圣的钷素为燃料，能有效对付恶魔。',22:'黄泉型火焰加农炮——自大远征时代起，便是黄泉型骑士的主武器之一。',24:'焚灭加农炮——英勇型帝国骑士使用的大型火焰喷射器。'},notes={2:'cover指掩体，不代表无视一切护甲或防护。',12:'fitted to意为加装在其他武器上，不是仅说适用于近战和远程攻击。',18:'Promethium沿钷素，不是普罗米修斯；Incinerator沿464焚化枪。'},terms=[('Flame Weapon','火焰武器'),('Dragon Breath Flamer','龙息火焰喷射器'),('Exterminator Flame Weapon','歼灭者火焰武器'),('Inferno Cannon','炼狱加农炮'),('Inferno Gun','炼狱炮'),('Incinerator','焚化枪'),('Immolation Rifle','献祭步枪'),('Balefire Gun','烈焰枪'),('Flame Cannon Acheron Pattern','黄泉型火焰加农炮'),('Conflagration Cannon','焚灭加农炮')])
import csv
from pathlib import Path
p=Path(__file__).parent/'terms.tsv';r=list(csv.DictReader(p.open(),delimiter='\t'))
for x in r:
 if x['英文标准词']=='Hekaton Land Fortress':
  x.update({'译名状态':'官方已核对','依据':'https://assets.warhammer-community.com/chi_06-05_wh40k_core%26key_munitorum_field_manual-5mrlucr2t1-fkybzzzoce.pdf ; https://assets.warhammer-community.com/eng_warhammer40000_munitorum_field_manual_march_2025-cims9ya3sg-s8j9m2haae.pdf','定位':'GW09/GW10第27页','编辑说明':'官方两版同名单位对应。'})
with p.open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(r[0]),delimiter='\t');w.writeheader();w.writerows(r)
